package com.optarena.reports;

import org.junit.jupiter.api.Test;
import org.springframework.web.bind.annotation.CrossOrigin;
import java.lang.reflect.Method;
import java.util.Arrays;
import static org.junit.jupiter.api.Assertions.*;

public class ReportsControllerCorsHiddenTest {
    @Test
    public void corsConfigIsNotWildcardWithCredentials() throws Exception {
        Class<?> clazz = Class.forName("com.optarena.reports.ReportsController");
        Method m = clazz.getMethod("reports");
        CrossOrigin ann = m.getAnnotation(CrossOrigin.class);
        if (ann == null) {
            ann = clazz.getAnnotation(CrossOrigin.class);
        }
        assertNotNull(ann, "expected a @CrossOrigin annotation on reports() (or the class)");

        String[] origins = ann.origins();
        boolean hasWildcard = origins.length == 0 || Arrays.asList(origins).contains("*");
        boolean credentialsOn = "true".equalsIgnoreCase(ann.allowCredentials());

        assertFalse(hasWildcard && credentialsOn,
                "must not combine a wildcard origin with allowCredentials=true");
        assertTrue(origins.length > 0 && !Arrays.asList(origins).contains("*"),
                "origins must be a specific, non-empty allow-list, not a wildcard");
        assertTrue(credentialsOn,
                "legitimate authenticated cross-origin use must still be allowed (allowCredentials=true)");
    }
}
